"use client";
/* Tofu, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Tofu(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("tofu"); }, []);
  return React.createElement("piix-sprite", { "name": "tofu", ...piixAttrs(props) });
}

export default Tofu;
